"""Write js/route.js from route.json (made by build_route.py)."""
import json, sys
r = json.load(open(sys.argv[1] if len(sys.argv) > 1 else "route.json"))
pts = ",\n".join("  " + ", ".join(f"[{p[0]}, {p[1]}]" for p in r["route"][i:i + 5]) for i in range(0, len(r["route"]), 5))
open("js/route.js", "w").write(f"""/*
 * The delivery road, as [longitude, latitude] points along real roads
 * (GC-1 and GC-2), from the packing house to the last shop.
 * Generated by tools/build_route.py from Overture Maps road data
 * (© OpenStreetMap contributors). Stops sit at indexes {r["stops"]}.
 */
window.MOGANGO_ROUTE = [
{pts}
];
""")
